import type { LatencyBreakdown, RasaExecutionTime, VoiceLatency } from "../types/conversation";

export function isLatencyBreakdown(breakdown: unknown): breakdown is LatencyBreakdown {
  if (typeof breakdown !== "object" || breakdown === null) return false;
  return "user_perceived_latency_ms" in breakdown;
}

export function isVoiceLatency(latency: unknown): latency is VoiceLatency {
  return (
    typeof latency === "object" &&
    latency !== null &&
    "tts_total_time_ms" in latency &&
    "tts_time_to_first_byte_ms" in latency &&
    typeof (latency as VoiceLatency).tts_total_time_ms === "number" &&
    typeof (latency as VoiceLatency).tts_time_to_first_byte_ms === "number"
  );
}
export function isRasaExecutionTime(executionTime: unknown): executionTime is RasaExecutionTime {
  return (
    typeof executionTime === "object" &&
    executionTime !== null &&
    "command_processor" in executionTime &&
    "prediction_loop" in executionTime &&
    typeof (executionTime as RasaExecutionTime).command_processor === "number" &&
    typeof (executionTime as RasaExecutionTime).prediction_loop === "number"
  );
}
